ExternalServiceRegistration.schema:
{
  "openapi": "3.0.1",
  "info": {
    "title": "ElevenLabs Twilio Outbound API",
    "description": "Especificacion reducida para llamadas salientes via Twilio",
    "version": "1.0.0"
  },
  "paths": {
    "/v1/convai/twilio/outbound-call": {
      "post": {
        "operationId": "makeTwilioCall",
        "summary": "Iniciar llamada saliente Twilio",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/TwilioCallPayload"
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Llamada iniciada",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/TwilioCallResponse"
                }
              }
            }
          }
        }
      }
    }
  },
  "components": {
    "schemas": {
      "TwilioCallPayload": {
        "type": "object",
        "properties": {
          "agent_id": {
            "type": "string",
            "description": "ID del agente en ElevenLabs"
          },
          "agent_phone_number_id": {
            "type": "string",
            "description": "ID del numero telefónico configurado en ElevenLabs"
          },
          "to_number": {
            "type": "string",
            "description": "Numero de destino en formato E.164"
          },
          "dynamic_variables": {
            "type": "object",
            "additionalProperties": { "type": "string" },
            "description": "Variables clave-valor para personalizar el prompt"
          }
        },
        "required": [
          "agent_id",
          "agent_phone_number_id",
          "to_number"
        ]
      },
      "TwilioCallResponse": {
        "type": "object",
        "properties": {
          "call_sid": {
            "type": "string"
          },
          "status": {
            "type": "string"
          }
        }
      }
    }
  }
}
